effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);

     vec2 TanRyu = 1.-acLayerNorm.st;

 	vec4 fragColor;

         highp vec4 textureColor1 = texture2DCv(comp.texture, acScreenNorm.st);
         highp vec4 RawText = texture2DCv(RAWT.texture, TanRyu);

         if(RAW) { gl_FragColor = RawText * texColor.a; return; }
         if(!enableLut) { gl_FragColor = textureColor1; return; }

         highp vec4 textureColor =vec4(textureColor1.rgb * pow(2.0, -0.2), textureColor1.w);
         mediump float blueColor = textureColor.b * 63.0;

         mediump vec2 quad1;
         quad1.y = floor(floor(blueColor) / 8.0);
         quad1.x = floor(blueColor) - (quad1.y * 8.0);

         mediump vec2 quad2;
         quad2.y = floor(ceil(blueColor) / 8.0);
         quad2.x = ceil(blueColor) - (quad2.y * 8.0);

         highp vec2 texPos1;
         texPos1.x = (quad1.x * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.r);
         texPos1.y = (quad1.y * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.g);
         texPos1.y = 1. - texPos1.y;

         highp vec2 texPos2;
         texPos2.x = (quad2.x * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.r);
         texPos2.y = (quad2.y * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.g);
         texPos2.y = 1. - texPos2.y;

         lowp vec4 newColor1 = texture2DCv(inputImg.texture, texPos1);
         lowp vec4 newColor2 = texture2DCv(inputImg.texture, texPos2);

         lowp vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
         fragColor = mix(textureColor, vec4(newColor.rgb, textureColor.w), lutLevel);

 	gl_FragColor = fragColor * texColor.a;

 }
